input.new_string:
"""Create an integer item from a number or string.

If ``raw`` is a string that is a valid TOML decimal integer (e.g. ``"1_000"``
or ``"+42"``), its formatting is preserved when rendered.
"""
value = int(raw)
if isinstance(raw, str):
    stripped = raw.strip()
    if _TOML_DEC_INT_RE.match(stripped):
        return Integer(value, Trivia(), stripped)
return item(value)

